import six
import copy


class DataCell(object):
    def __init__(self, **kwargs):
        for attribute_name in self._attribute_names():
            setattr(self, attribute_name, kwargs.get(attribute_name))

    @classmethod
    def column(cls):
        return ""

    @classmethod
    def name(cls):
        return ""

    @classmethod
    def partial_pattern(cls):
        return ""

    @classmethod
    def _attribute_names(cls):
        return '',

    @classmethod
    def _verify_class(cls, other):
        if not isinstance(other, cls):
            raise AttributeError("{} must be {} object.".format(other, cls.__name__))

    @classmethod
    def _verify_digital(cls, value):
        if not isinstance(value, six.integer_types) and not isinstance(value, float):
            raise AttributeError("{} must be digital.".format(value))

    def empty(self):
        pass

    def to_dict(self):
        if self.unit:
            return {'value': self.value, 'unit': self.unit}
        return {'value': self.value}

    @property
    def value(self):
        return ''

    @property
    def unit(self):
        return ''


