class IntervalCell(DataCell):
    start_attribute_name = 'interval_start'
    end_attribute_name = 'interval_end'

    @classmethod
    def column(cls):
        return "Interval"

    @classmethod
    def name(cls):
        return 'interval'

    @classmethod
    def partial_pattern(cls):
        return r'\s*(?P<{}>\d+.*)-\s*(?P<{}>\d+.*)\s*sec'.format(*cls._attribute_names())

    @classmethod
    def _attribute_names(cls):
        return cls.start_attribute_name, cls.end_attribute_name

    def __setattr__(self, key, value):
        if key in [self.start_attribute_name, self.end_attribute_name]:
            super(IntervalCell, self).__setattr__(key, float(value))
        else:
            super(IntervalCell, self).__setattr__(key, value)

    def __add__(self, rhs):
        copy_obj = copy.copy(self)
        if not isinstance(rhs, IntervalCell):
            raise AttributeError("{} must be InvertvalCell object".format(rhs))

        copy_obj.interval_start = \
            rhs.interval_start if rhs.interval_start < self.interval_start else self.interval_start
        copy_obj.interval_end = rhs.interval_end if rhs.interval_end > self.interval_end else self.interval_end
        return copy_obj

    def __mul__(self, rhs):
        # rhs should be integer or float
        return self

    def __div__(self, rhs):
        return self

    def __truediv__(self, rhs):
        return self

    def __sub__(self, rhs):
        self._verify_class(rhs)

        copy_obj = copy.copy(self)
        if self.interval_start > rhs.interval_start:
            raise ArithmeticError("interval on the left must cover the interval on the right in sub operation")

        if self.interval_end < rhs.interval_end:
            raise ArithmeticError("interval on the left must cover the interval on the right in sub operation")

        copy_obj.interval_start = rhs.interval_end
        copy_obj.interval_end = self.interval_end
        return copy_obj

    @property
    def value(self):
        return self.interval_start, self.interval_end

    @property
    def diff(self):
        return self.interval_end - self.interval_start

    @property
    def unit(self):
        return 'sec'


class TransferCell(DataCell):
    transfer_value_attribute_name = 'transfer_value'
    transfer_unit_attribute_name = 'transfer_unit'

    @classmethod
    def column(cls):
        return "Transfer"

    @classmethod
    def name(cls):
        return 'transfer'

    @classmethod
    def partial_pattern(cls):
        return r'(?P<{}>\d+.*)\s(?P<{}>\S+)'.format(*cls._attribute_names())

    @classmethod
    def _attribute_names(cls):
        return cls.transfer_value_attribute_name, cls.transfer_unit_attribute_name

    def __setattr__(self, key, value):
        if key == self.transfer_value_attribute_name:
            super(TransferCell, self).__setattr__(key, float(value))
        else:
            super(TransferCell, self).__setattr__(key, value)

    def __add__(self, rhs):
        self._verify_class(rhs)
        copy_obj = copy.copy(self)

        copy_obj.transfer_value = self.transfer_value + rhs.transfer_value
        # unit commonize is to do
        return copy_obj

    def __mul__(self, rhs):
        self._verify_digital(rhs)
        times = rhs
        copy_obj = copy.copy(self)
        copy_obj.transfer_value = self.transfer_value * times
        return copy_obj

    def __lt__(self, other):
        self._verify_class(other)
        return self.transfer_value < other.transfer_value

    def __gt__(self, other):
        self._verify_class(other)
        return self.transfer_value > other.transfer_value

    def __div__(self, rhs):
        self._verify_digital(rhs)
        times = rhs
        copy_obj = copy.copy(self)
        copy_obj.transfer_value = 1.0 * self.transfer_value / times
        return copy_obj

    def __truediv__(self, rhs):
        self._verify_digital(rhs)
        times = rhs
        copy_obj = copy.copy(self)
        copy_obj.transfer_value = self.transfer_value / times
        return copy_obj

    def empty(self):
        self.transfer_value = 0

    def __sub__(self, other):
        self._verify_class(other)
        copy_obj = copy.copy(self)
        copy_obj.transfer_value = self.transfer_value - other.transfer_value
        # unit commonize is to do
        return copy_obj

    @property
    def value(self):
        return self.transfer_value

    @property
    def unit(self):
        return self.transfer_unit


