class LostTotalDatagramsCell(DataCell):

    lost_attribute_name = 'lost'
    total_attribute_name = 'total'
    percentage_attribute_name = 'percentage'

    @classmethod
    def column(cls):
        return "Lost/Total Datagrams"

    @classmethod
    def name(cls):
        return 'datagrams'

    @classmethod
    def partial_pattern(cls):
        return r'(?P<{}>\d+)/\s*(?P<{}>\d+)\s\((?P<{}>\d+.*)%\)'.format(*cls._attribute_names())

    @classmethod
    def _attribute_names(cls):
        return cls.lost_attribute_name, cls.total_attribute_name, cls.percentage_attribute_name

    def __setattr__(self, key, value):
        if key in [self.lost_attribute_name, self.total_attribute_name]:
            super(LostTotalDatagramsCell, self).__setattr__(key, int(value))

            if hasattr(self, self.lost_attribute_name) and hasattr(self, self.total_attribute_name):
                lost = getattr(self, self.lost_attribute_name)
                total = getattr(self, self.total_attribute_name)
                if lost and total:
                    setattr(self, self.percentage_attribute_name, 1.0 * 100 * lost / total)
        elif key == self.percentage_attribute_name:
            value = self.lost / self.total * 100 if value is None else float(value)
            super(LostTotalDatagramsCell, self).__setattr__(key, value)
        else:
            super(LostTotalDatagramsCell, self).__setattr__(key, value)

    def __add__(self, rhs):
        self._verify_class(rhs)
        copy_obj = copy.copy(self)
        copy_obj.lost = self.lost + rhs.lost
        copy_obj.total = self.total + rhs.total
        copy_obj.percentage = 1.0 * 100 * copy_obj.lost / copy_obj.total
        return copy_obj

    def __mul__(self, rhs):
        self._verify_digital(rhs)
        times = rhs
        copy_obj = copy.copy(self)
        copy_obj.lost = self.lost * times
        copy_obj.total = self.total * times
        return copy_obj

    def __div__(self, rhs):
        self._verify_digital(rhs)
        times = rhs
        copy_obj = copy.copy(self)
        copy_obj.lost = 1.0 * self.lost / times
        copy_obj.total = 1.0 * self.total / times
        return copy_obj

    def __truediv__(self, rhs):
        self._verify_digital(rhs)
        times = rhs
        copy_obj = copy.copy(self)
        copy_obj.lost = 1.0 * self.lost / times
        copy_obj.total = 1.0 * self.total / times
        return copy_obj

    def empty(self):
        self.lost = 0
        self.total = 0
        self.percentage = 0.0

    def __sub__(self, rhs):
        self._verify_class(rhs)
        copy_obj = copy.copy(self)
        copy_obj.lost = self.lost - rhs.lost
        copy_obj.total = self.total - rhs.total
        copy_obj.percentage = 1.0 * 100 * copy_obj.lost / copy_obj.total if copy_obj.total else 0
        return copy_obj

    @property
    def value(self):
        return self.lost, self.total, self.percentage

    @property
    def unit(self):
        return '', '', '%'

    def __lt__(self, other):
        self._verify_class(other)
        if self.percentage == other.percentage:
            return self.total < other.total
        return self.percentage < other.percentage

    def __gt__(self, other):
        self._verify_class(other)
        if self.percentage == other.percentage:
            return self.total > other.total
        return self.percentage > other.percentage


